  dcMonthsShort: "muaj",
  faqTitle: "Pyetjet më të shpeshta",
  faqQ1: "A është vërtet falas AvokatIM për qytetarët?",
  faqA1: "Po. Pyetjet te Ava, postimi i rastit, drejtoria e avokatëve dhe veglat (afatet, dokumentet, kostoja gjyqësore, udhëzuesit) janë falas për qytetarët — paguajnë vetëm profesionistët për zyrën e tyre digjitale. Vetëm konsulta 30-minutëshe mund të ketë çmim nëse avokati e cakton, dhe çmimi shfaqet gjithmonë paraprakisht.",
  faqQ2: "A jep Ava këshilla ligjore?",
  faqA2: "Ava jep informacion ligjor nga ligjet e plota të Kosovës dhe nga praktika gjyqësore e publikuar (p.sh. e Gjykatës Supreme), me citim të burimit përkatës — jo këshilla ligjore. Për këshillë profesionale të lidhim menjëherë me një avokat të licencuar nga Oda e Avokatëve të Kosovës.",
  faqQ3: "Si funksionon postimi i rastit?",
  faqA3: "E përshkruan çështjen me pak fjalë dhe zgjedh fushën e qytetin. Avokatët e verifikuar që mbulojnë atë fushë njoftohen menjëherë dhe i pari që e merr rastin të kontakton. Emri yt i plotë i shfaqet vetëm avokatit që e merr rastin.",
  faqQ4: "Sa afat kam për ankesë ndaj një vendimi?",
  faqA4: "Zakonisht 15 ditë kalendarike nga dita e dorëzimit të vendimit, por afati varet nga procedura. Përdor kalkulatorin e afateve te faqja 'Afatet' ose pyete Avën me detajet e rastit tënd.",
  faqQ5: "Çfarë ndodh me të dhënat e mia?",
  faqA5: "Dokumentet ruhen të enkriptuara në serverët tanë, indeksimi bëhet lokalisht dhe teksti i tyre nuk u dërgohet shërbimeve të jashtme. Bisedat me Avën nuk ndahen me avokatët pa vendimin tënd.",
  faqQ6: "Çfarë të bëj nëse më ndal policia?",
  faqA6: "Shtyp butonin SOS — Ava të udhëzon me zë në kohë reale për të drejtat e tua, gjithçka regjistrohet si provë e enkriptuar dhe me një prekje njoftohen avokatët kujdestarë.",
