  landWhat1: "AvokatIM është ura mes qytetarëve dhe avokatëve të Kosovës. Për qytetarët është 'avokati i xhepit': asistentja Ava përgjigjet falas duke cituar nenet e ligjeve të Kosovës, tregu të lidh me avokatë të verifikuar, kurse butoni SOS të mbron në momentet më kritike.",
  landWhat2: "Për avokatët është një zyrë e plotë digjitale — lëndët, afatet, dokumentet, faturimi dhe asistenca AI — që i jep një avokati të vetëm kapacitetin e një zyre të tërë.",
