  dcPopular: "Most searched deadlines",
  dcDaysShort: "days",
  dcMonthsShort: "months",
  faqTitle: "Frequently asked questions",
  faqQ1: "Is AvokatIM really free for citizens?",
  faqA1: "Yes. Asking Ava, posting a case, the lawyer directory and the tools (deadlines, documents, litigation costs, guides) are free for citizens — only professionals pay for their digital office. Only the 30-minute consultation may have a price if the lawyer sets one, and it is always shown upfront.",
  faqQ2: "Does Ava give legal advice?",
  faqA2: "Ava gives legal information from the full laws of Kosovo and from published case law (e.g. the Supreme Court), citing the relevant source — not legal advice. For professional advice we connect you immediately with a lawyer licensed by the Kosovo Bar Association.",
  faqQ3: "How does posting a case work?",
  faqA3: "You describe the issue in a few words and pick the area and city. Verified lawyers covering that area are notified instantly and the first one to take the case contacts you. Your full name is shown only to the lawyer who takes the case.",
  faqQ4: "How long do I have to appeal a decision?",
  faqA4: "Usually 15 calendar days from the day the decision is served, but the deadline depends on the procedure. Use the deadline calculator on the 'Deadlines' page or ask Ava with the details of your case.",
  faqQ5: "What happens to my data?",
  faqA5: "Documents are stored encrypted on our own servers, indexing happens locally and their text is never sent to external services. Your conversations with Ava are not shared with lawyers without your decision.",
  faqQ6: "What should I do if the police stop me?",
  faqA6: "Press the SOS button — Ava guides you by voice in real time about your rights, everything is recorded as encrypted evidence and on-duty lawyers are notified with one tap.",
