  sosTitle: "SOS — Protection in the moment",
  sosSubtitle: "Three actions. Everything is recorded as evidence only with your consent.",
  sosConsentT: "Recording consent",
  sosConsentBody: "Audio is recorded and uploaded chunk by chunk IN REAL TIME to the AvokatIM server — so the evidence survives even if your phone is seized or damaged. It is stored encrypted, sealed with timestamps and hashes (chain of custody), and visible only to you and the lawyer who takes your case. Transcription uses local models — audio never leaves our server. Note: the legality of recording other people depends on the circumstances — this tool provides information, not legal advice.",
