  ntTitle: "Notaries of Kosovo",
  ntIntroT: "When you need a notary — and how to prepare",
  ntIntro: "A notary is a public officer: they certify contracts, draw up wills, resolve non-contentious inheritance and give documents legal force. The law requires appearing before the notary in person — but everything else you can prepare here: see which act you need, what documents to bring and roughly what it costs. Draft the document for free under Tools → Documents.",
