  ftSecurity: "Data security",
  secTitle: "Data security",
  secSubtitle: "Legal documents are among the most sensitive data there is. Here is how AvokatIM protects them — with technology, not promises.",
  secEncT: "Encryption at rest",
  secEncB: "Every document is stored encrypted (Fernet/AES). Even with physical access to the server, files are unreadable without the key.",
  secLocalT: "Local indexing — text never leaves the server",
  secLocalB: "Semantic document search uses local embeddings. Document content is never sent to external services for indexing.",
  secChainT: "Hash-chained evidence",
  secChainB: "Evidence recordings (SOS) are stored in SHA-256 hash-chained chunks — any later tampering is mathematically detectable. Chain-of-custody PDF certificate included.",
  secKillT: "External-AI kill switch",
  secKillB: "Each firm decides whether Ava may use external AI. With the switch OFF, everything is processed locally only (Law 06/L-082, art. 49).",
  secBackupT: "Daily encrypted backups",
  secBackupB: "A backup every night, AES-256 encrypted, with 30-day retention. Restores are tested and documented.",
  secLawT: "Compliant with Kosovo law",
  secLawB: "Data protection per Law 06/L-082, an audit log of every document action, and the right to erasure for clients.",
  secFooterNote: "Questions about security, or need a more detailed technical report for your firm? Write to us.",
  secVulnT: "Found a security vulnerability?",
  secVulnB: "Report it responsibly through the contact form (choose 'Complaint'). We confirm within 48 hours and keep you informed until it is resolved. Please do not exploit the issue or access other people's data.",
