  landTrust3: "Data stays in Kosovo",
  landWhatT: "What is AvokatIM?",
  landWhat1: "AvokatIM is the bridge between Kosovo's citizens and lawyers. For citizens it is a 'pocket lawyer': the assistant Ava answers for free citing the exact articles of Kosovo's laws, the marketplace connects you with verified lawyers, and the SOS button protects you in the most critical moments.",
  landWhat2: "For lawyers it is a complete digital office — matters, deadlines, documents, billing and AI assistance — giving a single lawyer the capacity of an entire firm.",
  landAvaT: "Ava — the free AI legal assistant",
  landAvaB: "Ask in your language and get answers citing the specific articles of Kosovo's laws and published case law. Ava speaks 6 languages and also works by voice — no account, no payment. And when you're ready for a lawyer, Ava structures your case from the conversation: category, city and urgency are filled in automatically.",
  landAvaCta: "Ask Ava",
  landSosT: "SOS — AI protection on your phone",
  landSosB: "Stopped by the police or in an urgent situation? Open SOS: talk to Ava by voice, everything is recorded as encrypted, timestamped and hash-chained evidence (PDF package), and one tap calls the on-duty lawyer.",
  landSosCta: "How SOS works",
  landSosSecLink: "How evidence is stored — Data security",
  landMarketT: "The marketplace and lawyer directory",
  landMarketB: "Lawyers verified with the Kosovo Bar Association, client reviews and transparent prices. Book a consultation online and pay by card when the lawyer has a fee — or post your case for free and lawyers contact you.",
  landMarketCta: "Browse lawyers",
  landToolsT: "Free legal tools",
  landToolsB: "Calculate legal deadlines (appeals, claims, objections) and generate official letters and complaints ready to submit — requests, consumer complaints, workplace notices, payment-order objections and more. Also estimate the cost of a lawsuit and read the free legal guides.",
  landToolsDeadlines: "Deadline calculator",
