  pushIosGuide: "On iOS push notifications require an installed app: open avokatiim.ai in Safari → Share button (square with arrow) → 'Add to Home Screen'. Then open AvokatIM from the home screen and enable notifications here.",
  refCount: "Offices referred so far: {n}",
