  lpFounderT: "Become a founder",
  lpFounderB: "The first 20 OAK-verified offices get the permanent 'Founder' badge in the public directory — and direct influence on the platform's development.",
  lpReferralHint: "Bring another office with your referral code from Settings — the basis for mutual benefits once the program goes live.",
  lpFeat1: "Matters, deadlines and documents in one place — every deadline with its procedural legal basis (LPK, LPP, LPA).",
  lpFeat2: "Ava, the AI assistant: deep legal research with citations from the Official Gazette and case law — the question is decomposed into sub-questions and returns a full analysis — plus document drafting and deadline extraction.",
  lpAiT: "Ava — your AI legal team",
  lpAiSub: "Four AI tools that work on the real laws of Kosovo, published case law and your case files — not generic opinions.",
  lpAi1T: "Deep research",
  lpAi1B: "Ava breaks the question into sub-questions, searches each one in the legal corpus and returns a structured analysis with cited articles and court decisions — step by step, before your eyes.",
  lpAi2T: "Improve with AI in templates",
  lpAi2B: "Give an instruction (e.g. 'strengthen the deadline clause') — get the new text, risk flags and a change list. You decide: accept or keep the original.",
  lpAi3T: "AI document summaries",
  lpAi3B: "Every court document is summarized into key points with possible deadlines — once per document, saved to the file.",
  lpAi4T: "Deadline extraction from documents",
  lpAi4B: "Ava finds the procedural dates and deadlines in a document and you add them to the calendar with one click — with the relevant legal basis.",
  lpOnboardHint: "Sign up and get active in ~5 minutes with the 3-step guide: public profile, OAK license, hours.",
  lpFeat3: "New clients from the Marketplace: citizens post cases, you choose which to take — with automatic conflict checking.",
  lpFeat4: "A client portal with messages, e-signatures and invoices — informed clients without the phone calls.",
  lpFeat5: "Time tracking, VAT invoicing and practice reports — ready for the tax administration.",
  lpFeat6: "Your data stays in Kosovo, encrypted — compliant with Law 06/L-082 on data protection.",
