  // Per-page intros / how-it-works
  introShow: "How does this page work?",
  introHide: "Got it",
  avaIntroT: "How to use Ava",
  avaIntro: "Write your question in your own language — Ava answers for free, citing the relevant article of Kosovo law and, where available, published case law. This is legal information, not legal advice: for your specific case, post it and a licensed lawyer will contact you.",
  postIntroT: "How posting a case works",
  postIntro: "Describe what happened in your own words — for free. Lawyers in the relevant field see the case without your full name; the conflict-of-interest check runs automatically. When a lawyer accepts your case you are notified by email and continue the conversation here.",
  myCaseIntroT: "My case — how to follow it",
  myCaseIntro: "Sign in with your email to see your case status, messages with your lawyer and documents. The SOS button is for urgent situations — your description goes instantly to on-duty lawyers and the first to take it contacts you.",
  lawyersIntroT: "The lawyer directory",
  lawyersIntro: "Every lawyer here is registered on the platform. Filter by practice area, city and language — then send your case directly to the lawyer you choose, or post it for everyone.",
  dashIntroT: "Dashboard — your day at a glance",
  dashIntro: "See your nearest deadlines, this week's hearings, active matters and open tasks. Start your day here: everything that needs attention today appears at the top.",
  intakeIntroT: "Intake — from request to matter",
  intakeIntro: "Every new client starts here: enter the parties and the description, the system checks conflicts of interest automatically, and one click turns the request into a matter with a full file.",
  mattersIntroT: "Matters — the digital file",
  mattersIntro: "Each matter holds the parties, deadlines computed automatically under the LPK/KPPRK/LKA, encrypted documents, notes, tasks and billed time. On documents use 'Extract deadlines' and 'Summarize with AI' — Ava reads the filings for you.",
  contactsIntroT: "Contacts — parties and clients",
  contactsIntro: "Your register of people and companies: clients, opposing parties, courts. From here you grant clients access to their portal and manage privacy consents (Law 06/L-082).",
  calendarIntroT: "Calendar — deadlines and hearings",
  calendarIntro: "All deadlines and hearings across your matters in one place. Legal deadlines are computed automatically with Kosovo's official holidays — email reminders arrive before they expire.",
  templatesIntroT: "Templates — documents in seconds",
  templatesIntro: "Pick a template (claim, appeal, power of attorney…), pick the matter — the fields fill themselves from the file. Then use 'Improve with AI': give an instruction and get the new text with risk flags — you decide whether to accept.",
  assistantIntroT: "Ava — your legal assistant",
  assistantIntro: "Ask about Kosovo law with article citations and published case law, request document summaries, deadline extraction or draft client communications. For complex questions turn on 'Deep research' — Ava breaks the question into sub-questions and returns a full cited analysis. Ava only sees your own office's matters.",
  billingIntroT: "Billing — from hours to payment",
  billingIntro: "Track hours with the timer, add expenses and issue a PDF invoice with VAT under the bar tariff. Clients pay online or by transfer; client (trust) funds are kept separately.",
  marketplaceIntroT: "Marketplace — new clients for you",
  marketplaceIntro: "Citizens post cases for free; you see the ones matching your profile's practice areas and cities. SOS cases appear first. When you claim a case, the conflict check runs automatically and it moves to Intake as a new request.",
  reportsIntroT: "Reports — your practice in numbers",
  reportsIntro: "Billable hours, revenue, matters by practice area and workload — see where your work is going.",
  settingsIntroT: "Settings — your office and profile",
  settingsIntro: "Manage your public directory profile (practice areas, cities, SOS duty), office users, the platform subscription and invoices, security (2FA) and backups.",
  hiwTitle: "How AvokatIM works",
