  faqQ1: "AvokatIM 对公民真的免费吗？",
  faqA1: "是的。向 Ava 提问、发布案件、律师目录和工具（期限、文书、诉讼费用、法律指南）对公民全部免费——只有专业人士为其数字办公室付费。仅当律师设定价格时，30 分钟咨询才可能收费，且价格始终提前显示。",
