  faqTitle: "Najčešća pitanja",
  faqQ1: "Da li je AvokatIM zaista besplatan za građane?",
  faqA1: "Da. Pitanja Avi, objavljivanje slučaja, imenik advokata i alati (rokovi, dokumenti, troškovi postupka, vodiči) besplatni su za građane — samo profesionalci plaćaju za svoju digitalnu kancelariju. Jedino 30-minutna konsultacija može imati cenu ako je advokat odredi, a cena se uvek prikazuje unapred.",
  faqQ2: "Da li Ava daje pravne savete?",
  faqA2: "Ava daje pravne informacije iz kompletnih zakona Kosova i objavljene sudske prakse (npr. Vrhovnog suda), uz citiranje relevantnog izvora — ne pravne savete. Za profesionalni savet odmah vas povezujemo sa advokatom licenciranim od Advokatske komore Kosova.",
  faqQ3: "Kako funkcioniše objavljivanje slučaja?",
  faqA3: "Opišete problem u nekoliko reči i izaberete oblast i grad. Verifikovani advokati koji pokrivaju tu oblast odmah dobijaju obaveštenje, a prvi koji preuzme slučaj vas kontaktira. Vaše puno ime vidi samo advokat koji preuzme slučaj.",
  faqQ4: "Koliki je rok za žalbu na odluku?",
  faqA4: "Obično 15 kalendarskih dana od dana dostavljanja odluke, ali rok zavisi od postupka. Koristite kalkulator rokova na stranici 'Rokovi' ili pitajte Avu sa detaljima vašeg slučaja.",
  faqQ5: "Šta se dešava sa mojim podacima?",
  faqA5: "Dokumenti se čuvaju šifrovani na našim serverima, indeksiranje se obavlja lokalno i njihov tekst se nikada ne šalje spoljnim servisima. Vaši razgovori sa Avom ne dele se sa advokatima bez vaše odluke.",
  faqQ6: "Šta da radim ako me zaustavi policija?",
  faqA6: "Pritisnite SOS dugme — Ava vas glasom u realnom vremenu vodi kroz vaša prava, sve se snima kao šifrovani dokaz i jednim dodirom se obaveštavaju dežurni advokati.",
