  dcMonthsShort: "ay",
  faqTitle: "Sık sorulan sorular",
  faqQ1: "AvokatIM vatandaşlar için gerçekten ücretsiz mi?",
  faqA1: "Evet. Ava'ya soru sormak, dava yayınlamak, avukat rehberi ve araçlar (süreler, belgeler, dava masrafı, rehberler) vatandaşlar için ücretsizdir — yalnızca profesyoneller dijital ofisleri için öder. Yalnızca 30 dakikalık danışmanlık, avukat belirlerse ücretli olabilir ve fiyat her zaman önceden gösterilir.",
  faqQ2: "Ava hukuki tavsiye veriyor mu?",
  faqA2: "Ava, Kosova'nın tüm yasalarından ve yayımlanmış içtihattan (örn. Yüksek Mahkeme) ilgili kaynağı göstererek hukuki bilgi verir — hukuki tavsiye değil. Profesyonel tavsiye için sizi hemen Kosova Barosu lisanslı bir avukatla buluştururuz.",
  faqQ3: "Dava yayınlamak nasıl çalışır?",
  faqA3: "Sorununuzu birkaç kelimeyle anlatır, alanı ve şehri seçersiniz. O alanı kapsayan doğrulanmış avukatlar anında bilgilendirilir ve davayı ilk üstlenen sizinle iletişime geçer. Tam adınız yalnızca davayı üstlenen avukata gösterilir.",
  faqQ4: "Bir karara itiraz için ne kadar sürem var?",
  faqA4: "Genellikle kararın tebliğinden itibaren 15 takvim günü, ancak süre usule bağlıdır. 'Süreler' sayfasındaki süre hesaplayıcısını kullanın veya davanızın ayrıntılarıyla Ava'ya sorun.",
  faqQ5: "Verilerime ne oluyor?",
  faqA5: "Belgeler kendi sunucularımızda şifreli saklanır, dizinleme yerel olarak yapılır ve metinleri asla dış hizmetlere gönderilmez. Ava ile konuşmalarınız sizin kararınız olmadan avukatlarla paylaşılmaz.",
  faqQ6: "Polis beni durdurursa ne yapmalıyım?",
  faqA6: "SOS düğmesine basın — Ava haklarınız konusunda gerçek zamanlı sesli rehberlik eder, her şey şifreli kanıt olarak kaydedilir ve tek dokunuşla nöbetçi avukatlar bilgilendirilir.",
