  landTrust3: "Veriler Kosova'da kalır",
  landWhatT: "AvokatIM nedir?",
  landWhat1: "AvokatIM, Kosova vatandaşları ile avukatları arasındaki köprüdür. Vatandaşlar için bir 'cep avukatı'dır: asistan Ava, Kosova yasalarının ilgili maddelerini kaynak göstererek ücretsiz yanıt verir, pazar yeri sizi doğrulanmış avukatlarla buluşturur ve SOS düğmesi en kritik anlarda sizi korur.",
  landWhat2: "Avukatlar için ise eksiksiz bir dijital ofistir — dosyalar, süreler, belgeler, faturalama ve AI desteği — tek bir avukata koca bir büronun kapasitesini verir.",
  landAvaT: "Ava — ücretsiz AI hukuk asistanı",
  landAvaB: "Kendi dilinizde sorun, Kosova yasalarının ilgili maddelerini ve yayımlanmış içtihadı kaynak gösteren yanıtlar alın. Ava 6 dil konuşur ve sesle de çalışır — hesap yok, ödeme yok. Avukata hazır olduğunuzda Ava davanızı konuşmadan yapılandırır: kategori, şehir ve aciliyet otomatik doldurulur.",
  landAvaCta: "Ava'ya sor",
  landSosT: "SOS — Telefonunuzda AI koruması",
  landSosB: "Polis mi durdurdu ya da acil bir durumda mısınız? SOS'u açın: Ava ile sesli konuşun, her şey şifreli, zaman damgalı ve hash zincirli kanıt olarak kaydedilir (PDF paketi) ve tek dokunuşla nöbetçi avukat aranır.",
  landSosCta: "SOS nasıl çalışır",
  landSosSecLink: "Kanıtlar nasıl saklanır — Veri güvenliği",
  landMarketT: "Pazar yeri ve avukat rehberi",
  landMarketB: "Kosova Barosu'nda doğrulanmış avukatlar, müvekkil yorumları ve şeffaf fiyatlar. Danışmayı çevrimiçi ayırtın ve avukatın ücreti varsa kartla ödeyin — veya davanızı ücretsiz yayınlayın, avukatlar sizinle iletişime geçsin.",
  landMarketCta: "Avukatlara göz at",
  landToolsT: "Ücretsiz hukuki araçlar",
  landToolsB: "Yasal süreleri hesaplayın (itirazlar, davalar) ve teslime hazır resmi dilekçe ve şikayetler oluşturun — talepler, tüketici şikayetleri, işveren ihtarları, ödeme emrine itiraz ve daha fazlası. Ayrıca dava masrafını hesaplayın ve ücretsiz hukuk rehberlerini okuyun.",
