  pushIosT: "iPhone/iPad — uygulama olarak yükleyin",
  pushIosGuide: "iOS'ta anlık bildirimler yüklü bir uygulama gerektirir: Safari'de avokatiim.ai'yi açın → Paylaş düğmesi (oklu kare) → 'Ana Ekrana Ekle'. Ardından AvokatIM'i ana ekrandan açın ve bildirimleri buradan etkinleştirin.",
