  lpFounderT: "Kuruculardan biri olun",
  lpFounderB: "Baro tarafından doğrulanan ilk 20 büro, herkese açık rehberde kalıcı 'Kurucu' rozetini alır — ve platformun gelişiminde doğrudan söz sahibi olur.",
  lpReferralHint: "Ayarlardaki yönlendirme kodunla başka bir büro getir — program devreye girdiğinde karşılıklı avantajların temeli.",
  lpFeat1: "Dosyalar, süreler ve belgeler tek yerde — her süre usul hukuku dayanağıyla (LPK, LPP, LPA).",
  lpFeat2: "AI asistanı Ava: Resmi Gazete ve içtihat atıflarıyla derin hukuki araştırma — soru alt sorulara bölünür ve tam analiz döner — ayrıca dilekçe taslağı ve süre çıkarma.",
  lpAiT: "Ava — senin AI hukuk ekibin",
  lpAiSub: "Kosova'nın gerçek yasaları, yayımlanmış içtihat ve dava dosyaların üzerinde çalışan dört AI aracı — genel görüşler değil.",
  lpAi1T: "Derin araştırma",
  lpAi1B: "Ava soruyu alt sorulara böler, her birini hukuk külliyatında arar ve madde ve karar atıflarıyla yapılandırılmış analiz döndürür — adım adım, gözlerinin önünde.",
  lpAi2T: "Şablonlarda AI ile iyileştir",
  lpAi2B: "Talimat ver (örn. 'süre maddesini güçlendir') — yeni metni, risk işaretlerini ve değişiklik listesini al. Karar senin: kabul et veya orijinali koru.",
  lpAi3T: "AI belge özetleri",
  lpAi3B: "Her mahkeme belgesi kilit noktalara ve olası sürelere özetlenir — belge başına bir kez, dosyaya kaydedilir.",
  lpAi4T: "Belgelerden süre çıkarma",
  lpAi4B: "Ava belgedeki usul tarihlerini ve sürelerini bulur, sen tek tıkla takvime eklersin — ilgili yasal dayanakla birlikte.",
  lpOnboardHint: "Kaydol ve 3 adımlı rehberle ~5 dakikada aktifleş: herkese açık profil, baro lisansı, saatler.",
  lpFeat3: "Pazardan yeni müvekkiller: vatandaşlar dava yayınlar, hangilerini alacağınızı siz seçersiniz — otomatik çıkar çatışması kontrolüyle.",
  lpFeat4: "Mesajlar, e-imzalar ve faturalarla müvekkil portalı — telefon trafiği olmadan bilgilendirilmiş müvekkil.",
  lpFeat5: "Çalışma saati kaydı, KDV'li faturalama ve büro raporları — vergi idaresine hazır.",
  lpFeat6: "Verileriniz Kosova'da kalır, şifrelenmiş — 06/L-082 sayılı veri koruma yasasına uygun.",
  lpPlansTitle: "Fiyatlar",
  lpPlanTrial: "1 yıl ücretsiz — tüm platform + ayda en fazla 5 Pazar davası.",
  lpPlanPaid: "24 €/kullanıcı/ay — her şey dahil: eksiksiz büro, SINIRSIZ Pazar davası, öne çıkan profil ve SOS nöbeti. Ücretlerinizden asla yüzde alınmaz.",
  // DE positioning: 0% commission + BRAK compliance (per-avokatet, DE host)
