  // Per-page intros / how-it-works
  introShow: "Bu sayfa nasıl çalışır?",
  introHide: "Anladım",
  avaIntroT: "Ava nasıl kullanılır",
  avaIntro: "Sorunuzu kendi dilinizde yazın — Ava, Kosova yasalarının ilgili maddesini ve varsa yayımlanmış içtihadı kaynak göstererek ücretsiz yanıtlar. Bu hukuki bilgilendirmedir, hukuki tavsiye değildir: somut durumunuz için davanızı yayınlayın, lisanslı bir avukat sizinle iletişime geçer.",
  postIntroT: "Dava yayınlama nasıl çalışır",
  postIntro: "Olanları kendi kelimelerinizle anlatın — ücretsiz. İlgili alandaki avukatlar davayı tam adınız olmadan görür; çıkar çatışması kontrolü otomatik yapılır. Bir avukat davanızı kabul ettiğinde e-posta ile bildirilirsiniz ve görüşmeye burada devam edersiniz.",
  myCaseIntroT: "Davam — nasıl takip edilir",
  myCaseIntro: "E-postanızla giriş yaparak davanızın durumunu, avukatla mesajlarınızı ve belgeleri görürsünüz. SOS düğmesi acil durumlar içindir — açıklamanız anında nöbetçi avukatlara gider ve ilk alan sizinle iletişime geçer.",
  lawyersIntroT: "Avukat rehberi",
  lawyersIntro: "Buradaki her avukat platformda kayıtlıdır. Alan, şehir ve dile göre filtreleyin — davanızı seçtiğiniz avukata doğrudan gönderin veya herkese yayınlayın.",
  dashIntroT: "Panel — gününüz tek bakışta",
  dashIntro: "En yakın süreleri, bu haftaki duruşmaları, aktif dosyaları ve açık görevleri görün. Güne buradan başlayın: bugün dikkat gerektiren her şey en üstte görünür.",
  intakeIntroT: "Kabul — talepten dosyaya",
  intakeIntro: "Her yeni müvekkil buradan başlar: tarafları ve açıklamayı girin, sistem çıkar çatışmasını otomatik kontrol eder ve tek tıkla talep tam dosyalı bir davaya dönüşür.",
  mattersIntroT: "Dosyalar — dijital dosya",
  mattersIntro: "Her dosyada taraflar, LPK/KPPRK/LKA'ya göre otomatik hesaplanan süreler, şifreli belgeler, notlar, görevler ve çalışma saatleri bulunur. Belgelerde 'Süreleri çıkar' ve 'AI ile özetle'yi kullanın — Ava dilekçeleri sizin yerinize okur.",
  contactsIntroT: "Kişiler — taraflar ve müvekkiller",
  contactsIntro: "Kişi ve şirket kaydınız: müvekkiller, karşı taraflar, mahkemeler. Buradan müvekkillere portal erişimi verir ve gizlilik onaylarını yönetirsiniz (06/L-082 sayılı Kanun).",
  calendarIntroT: "Takvim — süreler ve duruşmalar",
  calendarIntro: "Tüm dosyalarınızın süreleri ve duruşmaları tek yerde. Yasal süreler Kosova'nın resmi tatilleriyle otomatik hesaplanır — süre dolmadan e-posta hatırlatmaları gelir.",
  templatesIntroT: "Şablonlar — saniyeler içinde dilekçe",
  templatesIntro: "Şablonu seçin (dava dilekçesi, itiraz, vekaletname…), dosyayı seçin — alanlar dosya verilerinden kendiliğinden dolar. Sonra 'AI ile iyileştir'i kullanın: talimat verin, risk işaretli yeni metni alın — kabul edip etmemek size kalmış.",
  assistantIntroT: "Ava — hukuk asistanınız",
  assistantIntro: "Kosova yasalarını ve yayımlanmış içtihadı atıflarla sorun, belge özetleri, süre çıkarma veya müvekkil yazışma taslakları isteyin. Karmaşık sorular için 'Derin araştırma'yı açın — Ava soruyu alt sorulara böler ve atıflı tam analiz döndürür. Ava yalnızca kendi büronuzun dosyalarını görür.",
  billingIntroT: "Faturalama — çalışma saatinden ödemeye",
  billingIntro: "Saatleri zamanlayıcıyla kaydedin, masrafları ekleyin ve baro tarifesine göre KDV'li PDF fatura kesin. Müvekkil çevrimiçi veya havaleyle öder; müvekkil (emanet) fonları ayrı tutulur.",
  marketplaceIntroT: "Pazar — size yeni müvekkiller",
  marketplaceIntro: "Vatandaşlar davaları ücretsiz yayınlar; siz profilinizin alanları ve şehirleriyle eşleşenleri görürsünüz. SOS davaları önce görünür. Bir davayı aldığınızda çıkar çatışması kontrolü otomatik yapılır ve dava yeni talep olarak Kabul'e geçer.",
  reportsIntroT: "Raporlar — rakamlarla büronuz",
  reportsIntro: "Faturalanabilir saatler, gelir, alanlara göre dosyalar ve iş yükü — işinizin nereye gittiğini görün.",
  settingsIntroT: "Ayarlar — büronuz ve profiliniz",
  settingsIntro: "Rehberdeki genel profilinizi (alanlar, şehirler, SOS nöbeti), büro kullanıcılarını, platform aboneliği ve faturalarını, güvenliği (2FA) ve yedeklemeleri buradan yönetirsiniz.",
  hiwTitle: "AvokatIM nasıl çalışır",
  hiwSub: "Tek platform, iki dünya: vatandaşlar ücretsiz ve hızlı hukuki yardım alır — avukatlar eksiksiz dijital büro ve yeni müvekkiller kazanır.",
  hiw1T: "1. Sorun veya yayınlayın — ücretsiz",
  hiw1: "Ava'ya kendi dilinizde sorun veya davanızı anlatın. Bir avukat davayı kabul edene kadar kimliğiniz korunur.",
  hiw2T: "2. Pazar avukatınızı bulur",
