  dcMonthsShort: "mjeseci",
  faqTitle: "Najčešća pitanja",
  faqQ1: "Je li AvokatIM zaista besplatan za građane?",
  faqA1: "Da. Pitanja Avi, objavljivanje slučaja, imenik advokata i alati (rokovi, dokumenti, troškovi postupka, vodiči) besplatni su za građane — samo profesionalci plaćaju za svoj digitalni ured. Jedino 30-minutna konsultacija može imati cijenu ako je advokat odredi, a cijena se uvijek prikazuje unaprijed.",
  faqQ2: "Daje li Ava pravne savjete?",
  faqA2: "Ava daje pravne informacije iz kompletnih zakona Kosova i objavljene sudske prakse (npr. Vrhovnog suda), uz citiranje relevantnog izvora — ne pravne savjete. Za profesionalni savjet odmah vas povezujemo s advokatom licenciranim od Advokatske komore Kosova.",
  faqQ3: "Kako funkcionira objavljivanje slučaja?",
  faqA3: "Opišete problem u nekoliko riječi i izaberete oblast i grad. Verificirani advokati koji pokrivaju tu oblast odmah dobijaju obavijest, a prvi koji preuzme slučaj vas kontaktira. Vaše puno ime vidi samo advokat koji preuzme slučaj.",
  faqQ4: "Koliki je rok za žalbu na odluku?",
  faqA4: "Obično 15 kalendarskih dana od dana dostavljanja odluke, ali rok zavisi od postupka. Koristite kalkulator rokova na stranici 'Rokovi' ili pitajte Avu s detaljima vašeg slučaja.",
  faqQ5: "Šta se dešava s mojim podacima?",
  faqA5: "Dokumenti se čuvaju šifrirani na našim serverima, indeksiranje se obavlja lokalno i njihov tekst se nikada ne šalje vanjskim servisima. Vaši razgovori s Avom ne dijele se s advokatima bez vaše odluke.",
  faqQ6: "Šta da radim ako me zaustavi policija?",
  faqA6: "Pritisnite SOS dugme — Ava vas glasom u realnom vremenu vodi kroz vaša prava, sve se snima kao šifrirani dokaz i jednim dodirom se obavještavaju dežurni advokati.",
