  npTitle: "Ihr digitales Notariat — mit der Kraft der KI",
  npSubtitle: "Akten, Urkunden, Termine und Abrechnung an einem Ort — mit der Assistentin Ava, die das Notarrecht und die amtlichen Gebühren kennt. Gleicher Preis wie für Anwälte, das erste Jahr kostenlos.",
  npFeat1: "Ava mit dem Notarrecht: das Notargesetz, seine Änderungen und die amtliche Gebührenordnung — Antworten mit Quellenangaben in Sekunden.",
