  dcPopular: "Meistgesuchte Fristen",
  dcDaysShort: "Tage",
  dcMonthsShort: "Monate",
  faqTitle: "Häufig gestellte Fragen",
  faqQ1: "Ist AvokatIM für Bürger wirklich kostenlos?",
  faqA1: "Ja. Ava fragen, einen Fall einstellen, das Anwaltsverzeichnis und die Werkzeuge (Fristen, Dokumente, Prozesskosten, Ratgeber) sind für Bürger kostenlos — nur Berufsträger zahlen für ihr digitales Büro. Lediglich die 30-minütige Beratung kann einen Preis haben, wenn der Anwalt einen festlegt, und dieser wird immer vorab angezeigt.",
  faqQ2: "Erteilt Ava Rechtsberatung?",
  faqA2: "Ava liefert Rechtsinformationen aus den vollständigen Gesetzestexten und der veröffentlichten Rechtsprechung und zitiert die einschlägige Quelle — keine Rechtsberatung. Für professionelle Beratung verbinden wir Sie sofort mit einem bei der Anwaltskammer zugelassenen Anwalt.",
  faqQ3: "Wie funktioniert das Einstellen eines Falls?",
  faqA3: "Sie beschreiben das Anliegen in wenigen Worten und wählen Rechtsgebiet und Stadt. Verifizierte Anwälte, die dieses Gebiet abdecken, werden sofort benachrichtigt, und der erste, der den Fall übernimmt, kontaktiert Sie. Ihr vollständiger Name wird nur dem Anwalt angezeigt, der den Fall übernimmt.",
  faqQ4: "Wie lange habe ich Zeit, gegen eine Entscheidung Rechtsmittel einzulegen?",
  faqA4: "In der Regel 15 Kalendertage ab Zustellung der Entscheidung, aber die Frist hängt vom Verfahren ab. Nutzen Sie den Fristenrechner auf der Seite 'Fristen' oder fragen Sie Ava mit den Details Ihres Falls.",
  faqQ5: "Was passiert mit meinen Daten?",
  faqA5: "Dokumente werden verschlüsselt auf unseren eigenen Servern gespeichert, die Indexierung erfolgt lokal und ihr Text wird nie an externe Dienste gesendet. Ihre Unterhaltungen mit Ava werden ohne Ihre Entscheidung nicht mit Anwälten geteilt.",
  faqQ6: "Was soll ich tun, wenn mich die Polizei anhält?",
  faqA6: "Drücken Sie den SOS-Button — Ava führt Sie in Echtzeit per Stimme durch Ihre Rechte, alles wird als verschlüsselter Beweis aufgezeichnet und die Anwälte im Bereitschaftsdienst werden mit einem Tipp benachrichtigt.",
  // Payments: manual pay-by-link
  payLinkManualBtn: "Zahlungslink einfügen",
  payLinkEditBtn: "Zahlungslink bearbeiten",
