  sosTitle: "SOS — Schutz im entscheidenden Moment",
  sosSubtitle: "Drei Aktionen. Alles wird nur mit Ihrer Einwilligung als Beweis aufgezeichnet.",
  sosConsentT: "Einwilligung zur Aufnahme",
  sosConsentBody: "Audio wird aufgenommen und IN ECHTZEIT Stück für Stück auf den AvokatIM-Server hochgeladen — so bleibt der Beweis erhalten, selbst wenn Ihr Telefon beschlagnahmt oder beschädigt wird. Er wird verschlüsselt gespeichert, mit Zeitstempeln und Hashes versiegelt (Beweismittelkette) und ist nur für Sie und den Anwalt sichtbar, der Ihren Fall übernimmt. Die Transkription nutzt lokale Modelle — Audio verlässt unseren Server nie. Hinweis: Die Rechtmäßigkeit der Aufnahme anderer Personen hängt von den Umständen ab — dieses Werkzeug liefert Informationen, keine Rechtsberatung.",
