  landWhatT: "Was ist AvokatIM?",
  landWhat1: "AvokatIM ist die Brücke zwischen Bürgern und Anwälten. Für Bürger ist es ein 'Anwalt für die Hosentasche': Die Assistentin Ava antwortet kostenlos und zitiert die genauen Artikel der Gesetze, der Marktplatz verbindet Sie mit verifizierten Anwälten, und der SOS-Button schützt Sie in den kritischsten Momenten.",
  landWhat2: "Für Anwälte ist es ein komplettes digitales Büro — Akten, Fristen, Dokumente, Abrechnung und KI-Unterstützung — das einem einzelnen Anwalt die Kapazität einer ganzen Kanzlei gibt.",
  landAvaT: "Ava — die kostenlose KI-Rechtsassistentin",
  landAvaB: "Fragen Sie in Ihrer Sprache und erhalten Sie Antworten mit den konkreten Artikeln der Gesetze und der veröffentlichten Rechtsprechung. Ava spricht 6 Sprachen und funktioniert auch per Stimme — ohne Konto, ohne Bezahlung. Und wenn Sie bereit für einen Anwalt sind, strukturiert Ava Ihren Fall aus der Unterhaltung: Kategorie, Stadt und Dringlichkeit werden automatisch ausgefüllt.",
  landAvaCta: "Ava fragen",
  landSosT: "SOS — KI-Schutz auf Ihrem Telefon",
  landSosB: "Von der Polizei angehalten oder in einer Notsituation? Öffnen Sie SOS: Sprechen Sie mit Ava per Stimme, alles wird als verschlüsselter, zeitgestempelter und hash-verketteter Beweis aufgezeichnet (PDF-Paket), und ein Tipp ruft den Bereitschaftsanwalt.",
  landSosCta: "So funktioniert SOS",
  landSosSecLink: "Wie Beweise gespeichert werden — Datensicherheit",
  landMarketT: "Der Marktplatz und das Anwaltsverzeichnis",
  landMarketB: "Bei der Anwaltskammer verifizierte Anwälte, Mandantenbewertungen und transparente Preise. Buchen Sie eine Beratung online und zahlen Sie per Karte, wenn der Anwalt eine Gebühr festgelegt hat — oder stellen Sie Ihren Fall kostenlos ein und Anwälte kontaktieren Sie.",
  landMarketCta: "Anwälte durchsuchen",
  landToolsT: "Kostenlose Rechtswerkzeuge",
  landToolsB: "Berechnen Sie gesetzliche Fristen (Berufungen, Klagen, Widersprüche) und erstellen Sie einreichfertige offizielle Schreiben und Beschwerden — Anträge, Verbraucherbeschwerden, Schreiben an den Arbeitgeber, Widersprüche gegen Zahlungsbefehle und mehr. Berechnen Sie außerdem die Kosten eines Gerichtsverfahrens und lesen Sie die kostenlosen Ratgeber.",
  landToolsDeadlines: "Fristenrechner",
