  lpTitle: "Die ganze Kanzlei in Ihrer Hand — mit der Kraft der KI",
  lpSubtitle: "AvokatIM gibt Ihnen die Kraft einer ganzen Kanzlei: Akten, Fristen, Dokumente, Abrechnung, KI-Recherche und neue Mandanten von Bürgern — auf einer einzigen Plattform, in Ihrer Sprache.",
