  pushIosT: "iPhone/iPad — als App installieren",
  pushIosGuide: "Auf iOS erfordern Push-Benachrichtigungen eine installierte App: Öffnen Sie avokatiim.ai in Safari → Teilen-Button (Quadrat mit Pfeil) → 'Zum Home-Bildschirm'. Öffnen Sie AvokatIM dann vom Home-Bildschirm und aktivieren Sie hier die Benachrichtigungen.",
