  lpFounderT: "Werden Sie Gründungsmitglied",
  lpFounderB: "Die ersten 20 verifizierten Kanzleien erhalten das dauerhafte 'Gründungsmitglied'-Badge im öffentlichen Verzeichnis — und direkten Einfluss auf die Entwicklung der Plattform.",
  lpReferralHint: "Werben Sie eine weitere Kanzlei mit Ihrem Empfehlungscode aus den Einstellungen — die Grundlage für gegenseitige Vorteile, sobald das Programm startet.",
  lpFeat1: "Akten, Fristen und Dokumente an einem Ort — jede Frist mit ihrer verfahrensrechtlichen Grundlage.",
  lpFeat2: "Ava, die KI-Assistentin: tiefe Rechtsrecherche mit Zitaten aus dem Gesetzblatt und der Rechtsprechung — die Frage wird in Teilfragen zerlegt und liefert eine vollständige Analyse — plus Dokumententwürfe und Fristenextraktion.",
  lpAiT: "Ava — Ihr KI-Rechtsteam",
  lpAiSub: "Vier KI-Werkzeuge, die mit den echten Gesetzestexten, der veröffentlichten Rechtsprechung und Ihren Akten arbeiten — keine generischen Meinungen.",
  lpAi1T: "Tiefenrecherche",
  lpAi1B: "Ava zerlegt die Frage in Teilfragen, durchsucht den Rechtskorpus (Gesetze und Rechtsprechung) für jede einzelne und liefert eine strukturierte Analyse mit zitierten Artikeln und Entscheidungen — Schritt für Schritt, vor Ihren Augen.",
  lpAi2T: "Mit KI verbessern in Vorlagen",
  lpAi2B: "Geben Sie eine Anweisung (z. B. 'die Fristklausel verschärfen') — Sie erhalten den neuen Text, Risikohinweise und eine Änderungsliste. Sie entscheiden: übernehmen oder das Original behalten.",
  lpAi3T: "KI-Zusammenfassungen von Dokumenten",
  lpAi3B: "Jedes Gerichtsdokument wird in Kernpunkte mit möglichen Fristen zusammengefasst — einmal pro Dokument, in der Akte gespeichert.",
  lpAi4T: "Fristenextraktion aus Dokumenten",
  lpAi4B: "Ava findet die Verfahrensdaten und Fristen in einem Dokument und Sie übernehmen sie mit einem Klick in den Kalender — mit der einschlägigen Rechtsgrundlage.",
  lpOnboardHint: "Registrieren Sie sich und seien Sie in ~5 Minuten aktiv, mit dem 3-Schritte-Leitfaden: öffentliches Profil, Anwaltslizenz, Zeiten.",
  lpFeat3: "Neue Mandanten aus dem Marktplatz: Bürger stellen Fälle ein, Sie wählen aus, welche Sie übernehmen — mit automatischer Konfliktprüfung.",
  lpFeat4: "Ein Mandantenportal mit Nachrichten, E-Signaturen und Rechnungen — informierte Mandanten ohne die vielen Telefonanrufe.",
  lpFeat5: "Zeiterfassung, Rechnungen mit MwSt. und Kanzleiberichte — bereit für die Steuerverwaltung.",
  lpFeat6: "Ihre Daten bleiben verschlüsselt auf eigenen Servern — konform mit dem geltenden Datenschutzrecht.",
