  // Per-page intros / how-it-works
  introShow: "Wie funktioniert diese Seite?",
  introHide: "Verstanden",
  avaIntroT: "So nutzen Sie Ava",
  avaIntro: "Schreiben Sie Ihre Frage in Ihrer eigenen Sprache — Ava antwortet kostenlos und zitiert den einschlägigen Gesetzesartikel und — wo vorhanden — veröffentlichte Rechtsprechung. Dies ist Rechtsinformation, keine Rechtsberatung: Stellen Sie Ihren konkreten Fall ein und ein zugelassener Anwalt kontaktiert Sie.",
  postIntroT: "So funktioniert das Einstellen eines Falls",
  postIntro: "Beschreiben Sie in Ihren eigenen Worten, was passiert ist — kostenlos. Anwälte des einschlägigen Gebiets sehen den Fall ohne Ihren vollständigen Namen; die Prüfung auf Interessenkonflikte läuft automatisch. Wenn ein Anwalt Ihren Fall annimmt, werden Sie per E-Mail benachrichtigt und setzen die Unterhaltung hier fort.",
  myCaseIntroT: "Mein Fall — so verfolgen Sie ihn",
  myCaseIntro: "Melden Sie sich mit Ihrer E-Mail an, um den Status Ihres Falls, die Nachrichten mit Ihrem Anwalt und die Dokumente zu sehen. Der SOS-Button ist für Notsituationen — Ihre Beschreibung geht sofort an die Anwälte im Bereitschaftsdienst und der erste, der den Fall übernimmt, kontaktiert Sie.",
  lawyersIntroT: "Das Anwaltsverzeichnis",
  lawyersIntro: "Jeder Anwalt hier ist auf der Plattform registriert. Filtern Sie nach Rechtsgebiet, Stadt und Sprache — und senden Sie Ihren Fall direkt an den Anwalt Ihrer Wahl, oder stellen Sie ihn für alle ein.",
  dashIntroT: "Übersicht — Ihr Tag auf einen Blick",
  dashIntro: "Sehen Sie Ihre nächsten Fristen, die Verhandlungen dieser Woche, aktive Akten und offene Aufgaben. Beginnen Sie Ihren Tag hier: Alles, was heute Aufmerksamkeit braucht, erscheint ganz oben.",
  intakeIntroT: "Mandatsannahme — von der Anfrage zur Akte",
  intakeIntro: "Jeder neue Mandant beginnt hier: Erfassen Sie die Parteien und die Beschreibung, das System prüft automatisch auf Interessenkonflikte, und ein Klick macht aus der Anfrage eine Akte mit vollständigem Dossier.",
  mattersIntroT: "Akten — das digitale Dossier",
  mattersIntro: "Jede Akte enthält die Parteien, automatisch nach den Verfahrensgesetzen berechnete Fristen, verschlüsselte Dokumente, Notizen, Aufgaben und erfasste Zeit. Nutzen Sie bei Dokumenten 'Fristen extrahieren' und 'Mit KI zusammenfassen' — Ava liest die Schriftsätze für Sie.",
  contactsIntroT: "Kontakte — Parteien und Mandanten",
  contactsIntro: "Ihr Register der Personen und Unternehmen: Mandanten, Gegenparteien, Gerichte. Von hier aus gewähren Sie Mandanten Zugang zu ihrem Portal und verwalten die Datenschutz-Einwilligungen.",
  calendarIntroT: "Kalender — Fristen und Verhandlungen",
  calendarIntro: "Alle Fristen und Verhandlungen über Ihre Akten hinweg an einem Ort. Gesetzliche Fristen werden automatisch unter Berücksichtigung der gesetzlichen Feiertage berechnet — E-Mail-Erinnerungen kommen, bevor sie ablaufen.",
  templatesIntroT: "Vorlagen — Dokumente in Sekunden",
  templatesIntro: "Wählen Sie eine Vorlage (Klage, Berufung, Vollmacht…), wählen Sie die Akte — die Felder füllen sich aus dem Dossier von selbst. Nutzen Sie dann 'Mit KI verbessern': Geben Sie eine Anweisung und erhalten Sie den neuen Text mit Risikohinweisen — Sie entscheiden, ob Sie ihn übernehmen.",
  assistantIntroT: "Ava — Ihre Rechtsassistentin",
  assistantIntro: "Stellen Sie Rechtsfragen mit Artikel- und Rechtsprechungszitaten, fordern Sie Dokumentzusammenfassungen, Fristenextraktion oder Entwürfe für die Mandantenkommunikation an. Für komplexe Fragen aktivieren Sie 'Tiefenrecherche' — Ava zerlegt die Frage in Teilfragen und liefert eine vollständige Analyse mit Quellenangaben. Ava sieht nur die Akten Ihrer eigenen Kanzlei.",
  billingIntroT: "Abrechnung — von der Stunde zur Zahlung",
  billingIntro: "Erfassen Sie Stunden mit dem Timer, fügen Sie Auslagen hinzu und stellen Sie eine PDF-Rechnung mit MwSt. nach der Gebührenordnung aus. Mandanten zahlen online oder per Überweisung; Fremdgelder werden getrennt geführt.",
  marketplaceIntroT: "Marktplatz — neue Mandanten für Sie",
  marketplaceIntro: "Bürger stellen Fälle kostenlos ein; Sie sehen diejenigen, die zu den Rechtsgebieten und Städten Ihres Profils passen. SOS-Fälle erscheinen zuerst. Wenn Sie einen Fall übernehmen, läuft die Konfliktprüfung automatisch und er wandert als neue Anfrage in die Mandatsannahme.",
  reportsIntroT: "Berichte — Ihre Kanzlei in Zahlen",
  reportsIntro: "Abrechenbare Stunden, Umsatz, Akten nach Rechtsgebiet und Auslastung — sehen Sie, wohin Ihre Arbeit fließt.",
  settingsIntroT: "Einstellungen — Ihre Kanzlei und Ihr Profil",
  settingsIntro: "Verwalten Sie Ihr öffentliches Verzeichnisprofil (Rechtsgebiete, Städte, SOS-Bereitschaft), die Kanzleinutzer, das Plattform-Abonnement und die Rechnungen, die Sicherheit (2FA) und die Backups.",
  hiwTitle: "So funktioniert AvokatIM",
  hiwSub: "Eine Plattform, zwei Welten: Bürger erhalten kostenlose, schnelle Rechtshilfe — Anwälte ein komplettes digitales Büro und neue Mandanten.",
  hiw1T: "1. Fragen oder einstellen — kostenlos",
  hiw1: "Fragen Sie Ava in Ihrer eigenen Sprache oder beschreiben Sie Ihren Fall. Ihre Identität ist geschützt, bis ein Anwalt den Fall annimmt.",
  hiw2T: "2. Der Marktplatz findet Ihren Anwalt",
  hiw2: "Ihr Fall geht sofort an Anwälte des passenden Gebiets und der passenden Stadt, mit automatischer Prüfung auf Interessenkonflikte. Der erste, der annimmt, kontaktiert Sie.",
  hiw3T: "3. Verfolgen Sie alles in Ihrem Portal",
  hiw3: "Fallstatus, Verhandlungen, Nachrichten, Dokumente und Rechnungen — alles transparent, an einem Ort. Für Notfälle gibt es den SOS-Button mit Videoanrufen.",
  hiwFree: "Kostenlos für Bürger — für immer. Die Plattform wird durch die Abonnements der Anwälte finanziert und nimmt nie einen Anteil der Honorare.",
